<?php
require dirname(__DIR__,2).'/bootstrap.php';
use App\Services\CalendlyService;
try { $date=$_GET['date']??''; $tz=$_GET['timezone']??'America/Bogota'; if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))json_response(['message'=>'Fecha inválida'],422); $zone=new DateTimeZone($tz); $utcZone=new DateTimeZone('UTC'); $from=(new DateTimeImmutable($date.' 00:00:00',$zone))->setTimezone($utcZone); $to=$from->modify('+1 day'); $now=(new DateTimeImmutable('now',$utcZone))->modify('+1 minute'); if($from<$now)$from=$now; if($to<=$from)json_response(['slots'=>[]]); $data=(new CalendlyService)->availability($from->format('Y-m-d\TH:i:s\Z'),$to->format('Y-m-d\TH:i:s\Z')); $slots=[]; foreach($data['collection']??[] as $s){$local=(new DateTimeImmutable($s['start_time']))->setTimezone($zone);$slots[]=['start_time'=>$s['start_time'],'label'=>$local->format('g:i a')];} json_response(['slots'=>$slots]); } catch(Throwable $e){ json_response(['message'=>$e->getMessage()],503); }
